// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || 'local-dev-key';

function jsonResponse(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function notFound(res) {
  jsonResponse(res, 404, { code: 'project_not_found' });
}

function upstreamUnavailable(res) {
  jsonResponse(res, 502, { code: 'upstream_unavailable' });
}

function writeUncertain(res, observed) {
  jsonResponse(res, 504, { code: 'write_uncertain', observed: observed ?? null });
}

function conflict(res, current, conflicting_fields) {
  jsonResponse(res, 409, { code: 'edit_conflict', current, conflicting_fields });
}

function badRequest(res, statusCode, message) {
  jsonResponse(res, statusCode, { detail: message });
}

function validateEditableFields(body) {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return false;
  const keys = Object.keys(body);
  const expected = ['name', 'sector', 'country', 'stage', 'key_dates'];
  if (keys.length !== expected.length) return false;
  for (const k of expected) if (!(k in body)) return false;
  if (typeof body.name !== 'string' || !body.name.trim()) return false;
  if (typeof body.country !== 'string' || !body.country.trim()) return false;
  if (typeof body.sector !== 'string') return false;
  if (typeof body.stage !== 'string') return false;
  if (!Array.isArray(body.key_dates)) return false;
  for (const d of body.key_dates) {
    if (!d || typeof d !== 'object' || Array.isArray(d)) return false;
    if (Object.keys(d).length !== 2 || !('label' in d) || !('date' in d)) return false;
    if (typeof d.label !== 'string' || !d.label.trim()) return false;
    if (typeof d.date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(d.date)) return false;
  }
  return true;
}

function parseJsonBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => {
      data += chunk;
      if (data.length > 1e6) reject(new Error('payload too large'));
    });
    req.on('end', () => {
      if (!data) return resolve(null);
      try {
        resolve(JSON.parse(data));
      } catch {
        reject(new Error('invalid json'));
      }
    });
    req.on('error', reject);
  });
}

async function upstreamFetch(path, options = {}) {
  const url = new URL(path, UPSTREAM_URL);
  const headers = Object.assign(
    { 'X-Api-Key': UPSTREAM_API_KEY, 'accept': 'application/json' },
    options.headers || {}
  );
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), 5000);
  try {
    const res = await fetch(url, { ...options, headers, signal: controller.signal });
    return res;
  } finally {
    clearTimeout(t);
  }
}

async function readProject(projectId) {
  let res;
  try {
    res = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`);
  } catch {
    throw { type: 'upstream' };
  }
  if (res.status === 404) throw { type: 'not_found' };
  if (!res.ok) throw { type: 'upstream' };
  try {
    return await res.json();
  } catch {
    throw { type: 'upstream' };
  }
}

async function listProjects() {
  let res;
  try {
    res = await upstreamFetch('/projects');
  } catch {
    throw { type: 'upstream' };
  }
  if (!res.ok) throw { type: 'upstream' };
  try {
    return await res.json();
  } catch {
    throw { type: 'upstream' };
  }
}

function detailProjection(p) {
  return { id: p.id, name: p.name, sector: p.sector, country: p.country, stage: p.stage, key_dates: p.key_dates };
}

function summaryProjection(p) {
  return { id: p.id, name: p.name, sector: p.sector, country: p.country, stage: p.stage };
}

function mergeEdit(base, proposed, current) {
  const choose = (b, p, c) => {
    if (p === b) return [c, false];
    if (c !== b && c !== p) return [c, true];
    return [p, false];
  };
  const out = {};
  const conflicts = [];
  let r;
  [r, f] = choose(base.name, proposed.name, current.name); out.name = r; if (f) conflicts.push('name');
  [r, f] = choose(base.sector, proposed.sector, current.sector); out.sector = r; if (f) conflicts.push('sector');
  [r, f] = choose(base.country, proposed.country, current.country); out.country = r; if (f) conflicts.push('country');
  [r, f] = choose(base.stage, proposed.stage, current.stage); out.stage = r; if (f) conflicts.push('stage');
  [r, f] = choose(base.key_dates, proposed.key_dates, current.key_dates); out.key_dates = r; if (f) conflicts.push('key_dates');
  return { merged: out, conflicts, changed: JSON.stringify(out) !== JSON.stringify({
    name: current.name, sector: current.sector, country: current.country, stage: current.stage, key_dates: current.key_dates
  }) };
}

async function handle(req, res) {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/api/projects') {
    try {
      const projects = await listProjects();
      jsonResponse(res, 200, { projects: projects.map(summaryProjection) });
    } catch {
      upstreamUnavailable(res);
    }
    return;
  }

  const m = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (!m) {
    jsonResponse(res, 404, { detail: 'Not Found' });
    return;
  }
  const projectId = decodeURIComponent(m[1]);

  if (req.method === 'GET') {
    try {
      const project = await readProject(projectId);
      jsonResponse(res, 200, { project: detailProjection(project) });
    } catch (e) {
      if (e && e.type === 'not_found') return notFound(res);
      return upstreamUnavailable(res);
    }
    return;
  }

  if (req.method === 'PUT') {
    let body;
    try {
      body = await parseJsonBody(req);
    } catch {
      return badRequest(res, 422, 'Invalid JSON');
    }
    if (!body || typeof body !== 'object' || Array.isArray(body) || !('base' in body) || !('proposed' in body)) {
      return badRequest(res, 422, 'Invalid request body');
    }
    if (!validateEditableFields(body.base) || !validateEditableFields(body.proposed)) {
      return badRequest(res, 422, 'Invalid editable fields');
    }
    let current;
    try {
      current = await readProject(projectId);
    } catch (e) {
      if (e && e.type === 'not_found') return notFound(res);
      return upstreamUnavailable(res);
    }

    const result = mergeEdit(body.base, body.proposed, current);
    if (result.conflicts.length) {
      return conflict(res, detailProjection(current), result.conflicts);
    }
    if (!result.changed) {
      return jsonResponse(res, 200, { project: detailProjection(current) });
    }

    const payload = {
      name: result.merged.name,
      sector: result.merged.sector,
      country: result.merged.country,
      stage: result.merged.stage,
      key_dates: result.merged.key_dates,
      linked_companies: current.linked_companies,
    };

    let putRes;
    try {
      putRes = await upstreamFetch(`/projects/${encodeURIComponent(projectId)}`, {
        method: 'PUT',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
      });
    } catch {
      let observed = null;
      try {
        const reread = await readProject(projectId);
        observed = detailProjection(reread);
      } catch {}
      return writeUncertain(res, observed);
    }

    if (putRes.status === 404) return notFound(res);
    if (putRes.status === 504) {
      let observed = null;
      try {
        const reread = await readProject(projectId);
        observed = detailProjection(reread);
      } catch {}
      return writeUncertain(res, observed);
    }
    if (!putRes.ok) return upstreamUnavailable(res);

    try {
      const saved = await putRes.json();
      return jsonResponse(res, 200, { project: detailProjection(saved) });
    } catch {
      let observed = null;
      try {
        const reread = await readProject(projectId);
        observed = detailProjection(reread);
      } catch {}
      return writeUncertain(res, observed);
    }
  }

  jsonResponse(res, 405, { detail: 'Method Not Allowed' });
}

const server = http.createServer((req, res) => {
  handle(req, res).catch(() => upstreamUnavailable(res));
});

server.listen(PORT, '0.0.0.0');

// @ts-nocheck
const http = require('node:http');

const PORT = Number(process.env.PORT || 8080);
const UPSTREAM_URL = process.env.UPSTREAM_URL || 'http://127.0.0.1:8081';
const UPSTREAM_API_KEY = process.env.UPSTREAM_API_KEY || '';

function send(res, statusCode, body) {
  const payload = JSON.stringify(body);
  res.writeHead(statusCode, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function tryJson(value) {
  return JSON.parse(JSON.stringify(value));
}

function isObj(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
      if (data.length > 1e6) reject(new Error('payload too large'));
    });
